          file_mantra = $fopen("output.txt");//added
          $fwrite(file_mantra, "time, ");
      $fwrite(file_mantra, "clk_div,");

          $fwrite(file_mantra, "\n");//added
          forever begin
            #1
            $fwrite(file_mantra, "%0d, ", $time);
        $fwrite(file_mantra, "%h, ", clk_div);

            $fwrite(file_mantra, "\n");
          end
        end





// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;

    // 1. DECLARE VARIABLES FIRST (Top of block)


    // 2. THEN WAIT for original tests
    wait(llm_go_signal == 1);

    // 3. THEN execute logic
    // Initialize Inputs
    clk = 0;
    rst_n = 0;

    // Hold Reset to ensure clean state
    #20;

    // Release Reset
    rst_n = 1;
    #10;

    // Test Sequence 1: Normal Operation
    // Verify frequency division (Divide by 6)
    // Run for 24 clock cycles (4 full output periods) to establish baseline behavior
    for (i = 0; i < 24; i = i + 1) begin
        #5 clk = 1;
        #5 clk = 0;
    end

    // Test Sequence 2: Asynchronous Reset Verification
    // Drive partial sequence to increment counter to non-zero state
    #5 clk = 1; 
    #5 clk = 0; // cnt -> 1
    #5 clk = 1; 
    #5 clk = 0; // cnt -> 2 (Critical state before toggle)

    // Assert Reset Asynchronously (clk is low)
    // This checks if reset works independently of clock edge
    #2 rst_n = 0;
    #5 rst_n = 1;

    // Verify recovery (cnt should reset to 0, delaying the next toggle)
    for (i = 0; i < 12; i = i + 1) begin
        #5 clk = 1;
        #5 clk = 0;
    end

    // Test Sequence 3: Reset Sensitivity during Clock High
    // Targets edge sensitivity and priority logic (Async reset should work even if clk is high)
    #5 clk = 1;
    #2 rst_n = 0; // Assert reset while clk is high
    #2 rst_n = 1; // Release reset
    #1 clk = 0;

    // Run cycles to ensure state is clean and DUT recovers
    for (i = 0; i < 6; i = i + 1) begin
        #5 clk = 1;
        #5 clk = 0;
    end

    // Test Sequence 4: Clock Duty Cycle Variation
    // Targets edge detection logic robustness and potential hold time mutations
    for (i = 0; i < 6; i = i + 1) begin
        #2 clk = 1;
        #8 clk = 0;
    end

    // 4. Handover to Original Testbench
    llm_go_signal = 0;
end
// ============================================


